#[derive(sqlx::FromRow)]
pub struct UserRow { pub id: i64, pub name: String }

pub struct UsersGateway { pool: sqlx::PgPool }

impl UsersGateway {
    pub async fn find(&self, id: i64) -> sqlx::Result<Option<UserRow>> {
        sqlx::query_as::<_, UserRow>("SELECT id, name FROM users WHERE id = $1")
            .bind(id)
            .fetch_optional(&self.pool)
            .await
    }
}

